 setTransform(g,a,b,c,d,e,f){const sx=g===this.ctx?this.densityX||1:1,sy=g===this.ctx?this.densityY||1:1;g.setTransform(a*sx,b*sy,c*sx,d*sy,e*sx,f*sy);}
