 fence(g,x,y,length,vertical=false){for(let i=0;i<length;i+=26){let px=x+(vertical?0:i),py=y+(vertical?i:0);this.rect(g,px+3,py+9,9,6,'#38412d');this.rect(g,px,py-11,5,25,'#8b7851');this.rect(g,px,py-11,5,4,'#c2a573');if(i+26<length){this.rect(g,px,py-5,vertical?4:28,vertical?29:4,'#a08a5c');if(!vertical)this.rect(g,px,py+5,28,3,'#786244');}}}
 building(g,x,y,w,h,color,roof){this.poly(g,[[x,y],[x+w,y],[x+w+27,y+h+20],[x+25,y+h+20]],'#3d4732');this.rect(g,x,y,w,h,color);for(let i=8;i<w;i+=14)this.rect(g,x+i,y,2,h,'#00000020');this.rect(g,x,y+h-7,w,7,'#463a30');this.poly(g,[[x-12,y+12],[x+w/2,y-37],[x+w+12,y+12],[x+w+12,y+30],[x-12,y+30]],'#373a30');this.poly(g,[[x-12,y+12],[x+w/2,y-37],[x+w+12,y+12]],roof);for(let i=0;i<5;i++){let yy=y-27+i*10,ww=(i+1)*(w+24)/6;this.rect(g,x+w/2-ww/2,yy,ww,2,'#ffffff15');}this.rect(g,x-12,y+12,w+24,5,'#9b6546');this.rect(g,x-4,y+31,5,h-31,'#c8ad7d');this.rect(g,x+w-1,y+31,5,h-31,'#c8ad7d');}
