 this.poly(g,[[470,598],[553,598],[566,700],[545,820],[570,950],[552,1100],[566,1252],[476,1252],[462,1100],[484,950],[458,820],[478,700]],'#8c8054');this.poly(g,[[487,598],[529,598],[541,700],[521,820],[546,950],[528,1100],[540,1252],[500,1252],[486,1100],[508,950],[482,820],[500,700]],'#98885c');
 this.poly(g,[[480,436],[510,394],[380,210],[286,201],[263,224],[354,240],[451,410]],'#8c8054');
 this.poly(g,[[487,600],[529,600],[518,477],[531,430],[602,388],[694,293],[755,267],[748,258],[681,282],[584,374],[493,419],[488,484]],'#98885c');
 // Cart tracks from the barn doors out to the pasture gate, and a path to the lots east of the house.
 this.poly(g,[[214,246],[214,274],[40,274],[-44,226],[-44,204],[40,252]],'#857a50');this.poly(g,[[868,222],[1010,222],[1010,236],[868,240]],'#857a50');
 for(let i=0;i<17000;i++){let x=L+random()*WW,y=T+random()*WH;this.rect(g,x,y,2+(i%3)*2,2,i%6===0?'#8c8e5c':'#384c332c');if(i%11===0)this.rect(g,x+2,y-4,2,4,'#7a8052');}
 // Pond, muddy banks and reeds.
