 // Rain barrel and hay bales.
 this.rect(g,292,201,21,30,'#5c6350');this.rect(g,290,203,25,5,'#343e34');this.rect(g,290,222,25,4,'#343e34');this.rect(g,117,255,40,23,'#b89955');this.rect(g,120,254,35,4,'#dcc278');this.rect(g,128,255,4,23,'#7c683b');this.rect(g,145,255,4,23,'#7c683b');
