 // A scarecrow. The old supply crate's spot is now the generator lot.
 this.rect(g,589,312,5,42,'#9d7b4c');this.rect(g,576,320,31,5,'#a58b56');this.rect(g,583,314,16,16,'#a57843');this.rect(g,585,302,12,12,'#ccb773');this.rect(g,578,299,27,5,'#62553b');this.rect(g,584,292,15,9,'#8d7646');
