 for(let i=0;i<12;i++){let a=i*Math.PI/6;this.rect(g,650+Math.cos(a)*15,475+Math.sin(a)*9,7,5,'#919079');}this.rect(g,641,471,25,5,'#52422f');this.rect(g,648,468,6,12,'#785130');
 // A worn sign, stepping stones, flowers and fallen branches.
 this.rect(g,561,481,4,29,'#786441');this.rect(g,541,476,45,18,'#a48b56');g.fillStyle='#413b2b';g.font='bold 8px monospace';g.fillText('THE FARM',544,488);
 for(let i=0;i<18;i++){let x=321+random()*294,y=464+random()*95;this.rect(g,x,y,8,4,'#939278');this.rect(g,x,y,6,2,'#b0aa87');}
 for(let i=0;i<900;i++){let x=L+random()*WW,y=T+random()*WH;if(x>300&&x<640&&y>210&&y<450)continue;this.rect(g,x,y,2,7,'#53613c');this.rect(g,x-2,y-2,5,4,i%3===0?'#ccb36a':'#979c64');}
